mapper.select:
SELECT id, name, status, created_by, created_at, updated_at, 0 AS open_issue_count
FROM projects
WHERE id = #{id}

mapper.update:
UPDATE projects
SET name = #{name}

    , status = #{status}

WHERE id = #{id}

UPDATE projects
SET status = 'archived'
WHERE id = #{id}
  AND NOT EXISTS (
      SELECT 1
      FROM issues
      WHERE project_id = #{id}
        AND status != 'closed'
  )
